var bill = '100';
var tip = '20';
var people = '2';

function text(value, style) {
  return {type:'text', text:value, style:style || 'body'};
}

function savedValue(value, fallback) {
  if (typeof value === 'string' || typeof value === 'number') {
    return String(value).slice(0, 100);
  }
  return fallback;
}

function numberValue(raw) {
  var value = raw.trim();
  if (!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(value)) return null;
  var n = Number(value);
  return isFinite(n) ? n : null;
}

function money(n) {
  return '$' + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function render() {
  var nodes = [
    text('TIP CALCULATOR', 'eyebrow'),
    text('Split the bill', 'display'),
    text('Enter dollar amounts without currency symbols or commas.'),
    {type:'input', label:'Bill amount ($)', action:'bill', value:bill},
    {type:'input', label:'Tip percent (%)', action:'tip', value:tip},
    {type:'input', label:'People', action:'people', value:people}
  ];
  var b = numberValue(bill);
  var t = numberValue(tip);
  var p = numberValue(people);
  var errors = [];
  if (b === null || b < 0 || b > 1000000000) {
    errors.push('Bill: enter a number from 0 to 1,000,000,000.');
  } else {
    var decimal = bill.trim().split('.')[1];
    if (decimal && decimal.length > 2) errors.push('Bill: use no more than two decimal places.');
  }
  if (t === null || t < 0 || t > 1000) errors.push('Tip: enter a percentage from 0 to 1,000.');
  if (p === null || p < 1 || p > 1000000 || Math.floor(p) !== p) {
    errors.push('People: enter a whole number from 1 to 1,000,000.');
  }
  if (errors.length) {
    nodes.push(text('Check your inputs', 'subtitle'));
    for (var i = 0; i < errors.length; i++) nodes.push(text(errors[i]));
    nodes.push(text('Results appear when all inputs are valid.'));
  } else {
    var billCents = Math.round(b * 100);
    var tipCents = Math.round(billCents * t / 100);
    var totalCents = billCents + tipCents;
    var shareCents = Math.round(totalCents / p);
    nodes.push(text('RESULTS', 'eyebrow'));
    nodes.push(text('Tip: ' + money(tipCents / 100), 'subtitle'));
    nodes.push(text('Total: ' + money(totalCents / 100), 'subtitle'));
    nodes.push(text(money(shareCents / 100) + ' per person', 'display'));
    nodes.push(text('Tip is calculated on the entered bill and rounded to the nearest cent.'));
    if (shareCents * p !== totalCents) {
      nodes.push(text('Per-person total is rounded; equal rounded shares may not add up exactly to the bill total.'));
    }
  }
  nodes.push({type:'button', label:'Reset to 100 / 20% / 2 people', action:'reset'});
  nodes.push(text('Inputs are saved locally on this device. Works offline.'));
  return {type:'column', children:nodes};
}

function dispatch(jsonText) {
  var event;
  try { event = JSON.parse(jsonText); } catch (e) { event = {}; }
  if (!event || typeof event !== 'object') event = {};
  var changed = false;
  if (event.type === 'init') {
    var stored = event.storage || {};
    bill = savedValue(stored.bill, '100');
    tip = savedValue(stored.tip, '20');
    people = savedValue(stored.people, '2');
  } else if (event.type === 'input') {
    if (typeof event.value === 'string') {
      var value = event.value.slice(0, 100);
      if (event.action === 'bill') { bill = value; changed = true; }
      if (event.action === 'tip') { tip = value; changed = true; }
      if (event.action === 'people') { people = value; changed = true; }
    }
  } else if (event.type === 'action' && event.action === 'reset') {
    bill = '100'; tip = '20'; people = '2'; changed = true;
  }
  var effects = [];
  if (changed) effects.push({type:'storage.save', data:{bill:bill, tip:tip, people:people}});
  return JSON.stringify({ui:render(), effects:effects});
}
